/**
 * react-syntax-highlighter ESM 子路径缺类型声明(root 包只给 index 的 d.ts)。
 * 为什么必须走子路径:root barrel `dist/esm/index.js` 会连带求值 `light-async.js`,
 * 后者静态引入 190 个 `highlight.js/lib/languages/*`;本仓装的 highlight.js 缺
 * `sql_more.js` 等条目 ⇒ Next dev 编译期直接 module-not-found(整页 500)。
 * 三处消费方(markdown-stream / docs/code-block / media/SyntaxHighlighter)只用 Prism,
 * 故直接 import `dist/esm/prism`(默认导出即 highlighter 组件),避免 barrel 拉进 Light。
 */
declare module 'react-syntax-highlighter/dist/esm/prism' {
  import type { Prism as PrismComponent } from 'react-syntax-highlighter'
  const Prism: typeof PrismComponent
  export default Prism
}
// ⁠​‌​​‌​​‌‍‍​‌​​‌​​​‍‍​‌​‌​‌​‌‍‍​‌​​‌​​‌‍‍​​‌​‌‌​‌‍‍​‌​​​​​‌‍‍​‌​​‌​​‌‍‍‌​‌‌​‌‌‌‍‍‌‌​​‌‌​​‌‌‌‌​‌​‍‍‌‌​‌‌​​​‌​​​‌‌‌‍‍​‌​​​​​‌‍‍​‌​​‌​​‌‍‍‌​‌‌​‌‌‌‍‍‌‌​​‌‌‌​‌​​‌‌‌​‍‍‌‌​​‌‌​​​‌​​‌​‌‍‍‌​‌‌‌​‌‌‌​‌‌‌​‌‍‍‌​‌‌​‌‌‌‍‍​‌​​‌‌​​‍‍​‌​​​​‌‌‍‍‌​‌‌​‌‌‌‍‍​‌‌​​​​‌‍‍​‌‌​‌​​‌‍‍​‌‌‌‌​‌​‍‍​‌‌​‌​​​‍‍​‌‌‌​​‌‌‍‍​​‌​‌‌‌​‍‍​‌‌‌​‌​​‍‍​‌‌​‌‌‌‌‍‍​‌‌‌​​​​‍‍‌​‌‌​‌‌‌‍‍​‌​‌​​​​‍‍​‌​‌​​‌​‍‍​‌​​‌‌‌‌‍‍​‌​‌​‌‌​‍‍​‌​​​‌​‌‍‍​‌​​‌‌‌​‍‍​‌​​​​​‌‍‍​‌​​‌‌‌​‍‍​‌​​​​‌‌‍‍​‌​​​‌​‌‍‍​​‌​‌‌​‌‍‍​​‌‌​​‌​‍‍​​‌‌​​​​‍‍​​‌‌​​‌​‍‍​​‌‌​‌‌​⁠
